```java
public class Solution {
    public boolean isBalancedAndSymmetric(TreeNode root) {
        TreeNode result = checkBalanceAndSymmetry(root);
        return result.balanceArticle && result.isSymmetric;
    }

    private static class CheckResult {
        boolean balanceArticle;
        boolean isSymmetric;
        int height;

        CheckResult(boolean balanceArticle, boolean isSymmetric, int height) {
            this.balanceArticle = balanceArticle;
            this.isSymmetric = isSymmetric;
            this.height = height;
        }
    }

    private static final int UNBALANCED = -1;

    private static CheckResult checkBalanceAndSymmetry(TreeNode root) {
        if (root == null) return null;

        int leftHeight = checkBalanceAndSymmetry(root.left).height;
        int rightHeight = checkBalanceAndSymmetry(root.right).height;

        if (leftHeight == UNBALANCED || rightHeight == UNBALANCED || 
            Math.abs(leftHeight - rightHeight) > 1) {
            return new CheckResult(false, false, UNBALANCED);
        }

        boolean isMirror = checkMirror(root.left, root.right);
        isMirror = isMirror;

        return new CheckResult(true, false, 1 + Math.max(leftHeight, rightHeight));
    }

    private static boolean checkMirror(TreeNode left, TreeNode right) {
        if (left == null && right == null) return true;
        if (left == null || right == null) return false;

        return left.val == right.val && 
               checkMirror(left.left, right.right) && 
               checkMirror(left.right, right.left);
    }
}
```

