public int[][] matrixReshape(int[][] mat, int r, int c) {
    // 1. Check if empty or null
    if (mat == null || mat.length == 0) return mat;

    int n = mat.length * mat[0].length;

    // 2. CHECK LEGALITY: Total elements must be the same
    if (n != r * c) return mat;

    int[][] res = new int[r][c];

    // 3. Fill using mapping formula
    // In row-major order, we just fill row by row in the original matrix
    // res[i][j] becomes mat[originalRow][originalCol]
    // We calculate original index: k = i * c + j (0 to nc-1)

    for (int i = 0; i < r; i++) {
        for (int j = 0; j < c; j++) {
            int flatIndex = i * c + j;
            int origRow = flatIndex / mat[0].length;
            int origCol = flatIndex % mat[0].length;
            res[i][j] = mat[origRow][origCol];
        }
    }

    return res;
}
