```java
public class PairCounter {

    // Main entry point (optional helper works, but direct recursion on signature is cleaner per requirement)
    public static int countPairs(int[] arr) {
        if (arr == null || arr.length == 0) return 0;
        return countPairsRecursive(arr, 0);
    }

    // Recursive helper to count pairs
    private static int countPairsRecursive(int[] arr, int index) {
        // Base case: Stop if we are past the last possible pair.
        // A pair exists at indices 0 to 1, 1 to 2, ..., len-2 to len-1.
        // So we stop if index is at the length - 1 or beyond.
        if (index >= arr.length - 1) {
            return 0;
        }

        int count = 0;
        // Check: First element is exactly twice the second element
        if (arr[index] == 2 * arr[index + 1]) {
            count = 1;
        }

        // Recursive step
        return count + countPairsRecursive(arr, index + 1);
    }

    public static void main(String[] args) {
        int[] test = {4, 2, 8, 4, 6, 3};
        // Output: 2
        System.out.println(countPairs(test)); 
    }
}
```

